    cbar = next(c for c in range(w) if all(grid[r][c] == 4 for r in range(h)))
    tile = [row[:cbar] for row in grid[:rbar]]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r == rbar or c == cbar:
                out[r][c] = 4
            else:
                out[r][c] = tile[r % rbar][c % cbar]
